#include "raylib.h"
#include <algorithm>
#include <fstream>
#include <string>
#include <vector>

enum class Tile { Empty, Road, Residential, Commercial, Industrial, Power, Park, Sports, Parking, Police, Hospital, Fire, Cemetery };
enum class Tool { Navigate, Road, Residential, Commercial, Industrial, Power, Park, Sports, Parking, Police, Hospital, Fire, Cemetery, Bulldoze };
struct Data { const char* name; int cost; Color color; int pop; int mw; };
static constexpr int W=18,H=12,S=42,X=24,Y=92;
Data data(Tile t){switch(t){case Tile::Road:return{"Estrada",10,{90,94,98,255},0,0};case Tile::Residential:return{"Residencial",100,{181,112,78,255},12,0};case Tile::Commercial:return{"Comercial",150,{72,135,188,255},4,0};case Tile::Industrial:return{"Industrial",200,{191,156,67,255},3,0};case Tile::Power:return{"Usina",1000,{188,73,62,255},0,120};case Tile::Park:return{"Parque",250,{56,145,78,255},0,0};case Tile::Sports:return{"Esportes",350,{74,151,145,255},0,0};case Tile::Parking:return{"Estacionar",180,{116,116,125,255},0,0};case Tile::Police:return{"Delegacia",500,{61,93,173,255},0,0};case Tile::Hospital:return{"Hospital",800,{205,235,226,255},0,0};case Tile::Fire:return{"Bombeiros",600,{211,82,46,255},0,0};case Tile::Cemetery:return{"Cemiterio",400,{103,91,121,255},0,0};default:return{"Navegar",0,{0,0,0,0},0,0};}}
Tile tile(Tool t){switch(t){case Tool::Road:return Tile::Road;case Tool::Residential:return Tile::Residential;case Tool::Commercial:return Tile::Commercial;case Tool::Industrial:return Tile::Industrial;case Tool::Power:return Tile::Power;case Tool::Park:return Tile::Park;case Tool::Sports:return Tile::Sports;case Tool::Parking:return Tile::Parking;case Tool::Police:return Tile::Police;case Tool::Hospital:return Tile::Hospital;case Tool::Fire:return Tile::Fire;case Tool::Cemetery:return Tile::Cemetery;default:return Tile::Empty;}}
void reset(std::vector<Tile>& m,int& money,int& day){m.assign(W*H,Tile::Empty);money=100000;day=1;}
int main(){InitWindow(1280,720,"Metropolis KayKit - C++");SetTargetFPS(60);std::vector<Tile> m;int money=100000,day=1,speed=1;float timer=0;bool pause=false;Tool selected=Tool::Navigate;reset(m,money,day);Color bg={245,237,218,255},ink={38,47,52,255},grass={61,107,51,255},panel={250,246,235,255};
while(!WindowShouldClose()){if(IsKeyPressed(KEY_ESCAPE)||IsMouseButtonPressed(MOUSE_BUTTON_RIGHT))selected=Tool::Navigate;if(IsKeyPressed(KEY_SPACE))pause=!pause;if(IsKeyPressed(KEY_ONE))speed=1;if(IsKeyPressed(KEY_TWO))speed=2;if(IsKeyPressed(KEY_FIVE))speed=5;if(IsKeyPressed(KEY_R))reset(m,money,day);if(IsKeyPressed(KEY_S)){std::ofstream f("metropolis_save.txt");f<<money<<' '<<day;}if(!pause&&(timer+=GetFrameTime()*speed)>8){timer=0;day++;int p=0;for(auto t:m)p+=data(t).pop;money+=p/2-15;}
if(IsMouseButtonPressed(MOUSE_BUTTON_LEFT)){Vector2 q=GetMousePosition();int cx=(int)(q.x-X)/S,cy=(int)(q.y-Y)/S;if(cx>=0&&cx<W&&cy>=0&&cy<H&&selected!=Tool::Navigate){int i=cy*W+cx,c=selected==Tool::Bulldoze?20:data(tile(selected)).cost;if(money>=c&&(selected==Tool::Bulldoze||m[i]==Tile::Empty)){money-=c;m[i]=selected==Tool::Bulldoze?Tile::Empty:tile(selected);}}}
int pop=0,power=0;for(auto t:m){pop+=data(t).pop;power+=data(t).mw;}BeginDrawing();ClearBackground(bg);DrawRectangle(0,0,1280,68,ink);DrawText("METROPOLIS KAYKIT",24,15,28,bg);DrawText(TextFormat("Dia %d  -  %s",day,pause?"Pausado":"Crescimento Estavel"),420,24,18,bg);DrawText(TextFormat("R$ %d",money),1090,20,22,{255,218,125,255});DrawRectangle(X-8,Y-8,W*S+16,H*S+16,{43,70,40,255});DrawRectangle(X,Y,W*S,H*S,grass);
for(int y=0;y<H;y++)for(int x=0;x<W;x++){Tile t=m[y*W+x];Rectangle r={(float)(X+x*S),(float)(Y+y*S),(float)S-1,(float)S-1};if(t==Tile::Empty)DrawRectangleRec(r,grass);else{DrawRectangleRec(r,data(t).color);if(t==Tile::Road)DrawLine((int)r.x+4,(int)r.y+21,(int)r.x+37,(int)r.y+21,{230,197,74,255});else{DrawRectangle((int)r.x+8,(int)r.y+9,26,22,{245,225,184,255});}}}
int px=X+W*S+24;DrawRectangle(px,84,336,570,panel);DrawText("INDICADORES",px+18,101,20,ink);const char* n[]={"Fundos","Lucro / Dia","Populacao","Emprego","Felicidade","Crime","Saude","Energia"};const char* v[]={TextFormat("R$ %d",money),TextFormat("+R$ %d",pop/2-15),TextFormat("%d",pop),"100%","100%","0%","100%",TextFormat("%d / %d MW",pop/3,power)};for(int i=0;i<8;i++){DrawText(n[i],px+18,136+i*28,16,{90,94,91,255});DrawText(v[i],px+185,136+i*28,16,ink);}DrawText("FERRAMENTAS",px+18,380,20,ink);Tool tools[]={Tool::Road,Tool::Residential,Tool::Commercial,Tool::Industrial,Tool::Power,Tool::Park,Tool::Sports,Tool::Police,Tool::Hospital,Tool::Fire,Tool::Bulldoze};for(int i=0;i<11;i++){int bx=px+16+(i%2)*158,by=414+(i/2)*34;Rectangle b={(float)bx,(float)by,150,28};bool active=selected==tools[i];DrawRectangleRec(b,active?Color{72,121,75,255}:Color{223,216,199,255});DrawText(TextFormat("%s R$ %d",data(tile(tools[i])).name,tools[i]==Tool::Bulldoze?20:data(tile(tools[i])).cost),bx+7,by+6,12,active?RAYWHITE:ink);if(CheckCollisionPointRec(GetMousePosition(),b)&&IsMouseButtonPressed(MOUSE_BUTTON_LEFT))selected=tools[i];}DrawText(TextFormat("Selecionado: %s | Espaco pausa | S salva | R reinicia",data(tile(selected)).name),24,648,16,ink);DrawText(TextFormat("Velocidade: %dx",speed),24,674,15,{90,94,91,255});EndDrawing();}CloseWindow();}
